export const BUNDLED_PACK_LESSON_RAW = "{\n  \"canonicalId\": \"lesson-cardiac-conduction-physiology-01\",\n  \"packId\": \"pack-cardio-histology-ar-v1\",\n  \"organId\": \"organ-heart\",\n  \"systemId\": \"sys-cardiovascular\",\n  \"revision\": 1,\n  \"titleAr\": \"فسيولوجيا نظام التوصيل الكهربائي للقلب (Systema conducens cordis)\",\n  \"titleEn\": \"Physiology of the Cardiac Conduction System (Systema conducens cordis)\",\n  \"reviewStatus\": \"EDUCATIONAL_FOUNDATION_UNREVIEWED_CLINICALLY\",\n  \"importedAt\": \"2026-10-22T00:00:00Z\",\n  \"humanReviewedAt\": null,\n  \"license\": \"CC-BY-4.0 (Original Dawa & Hayah Educational Synthesis)\",\n  \"attribution\": \"دواء وحياة — إعداد علمي تأسيسي استناداً إلى Terminologia Anatomica ومراجع الفسيولوجيا القياسية\",\n  \"sectionsAr\": [\n    {\n      \"heading\": \"1. العقدة الجيبية الأذينية (Nodus sinuatrialis)\",\n      \"body\": \"تقع في الجدار العلوي للأذين الأيمن قرب فتحة الوريد الأجوف العلوي، وتعمل كمنظم ضربات طبيعي أولي للقلب (Pacemaker) عبر توليد كمون الفعل تلقائياً نتيجة تدفق أيونات الصوديوم والكالسيوم عبر قنوات الغشاء الخلوي.\"\n    },\n    {\n      \"heading\": \"2. العقدة الأذينية البطينية وحزمة هيس (Nodus atrioventricularis & Fasciculus atrioventricularis)\",\n      \"body\": \"تؤخر العقدة الأذينية البطينية الإشارة الكهربائية لنحو 0.09 ثانية تقريباً في الحالة الفسيولوجية، مما يسمح بانقباض الأذينين وامتلاء البطينين بالدم قبل بدء الانقباض البطيني عبر حزمة هيس وألياف بوركينجي.\"\n    },\n    {\n      \"heading\": \"3. الارتباط الدوائي التعليمي (غير علاجي)\",\n      \"body\": \"توضح دراسة قنوات الأيونات والمستقبلات الأدرينالية بيتا-1 (Beta-1 Adrenoceptors) في خلايا التوصيل كيف تؤثر الفئات الدوائية نظرياً على سرعة التوصيل (Dromotropy) ومعدل النبض (Chronotropy). هذه المادة مخصصة للفهم الفسيولوجي الأكاديمي فقط وليست دليلاً علاجياً.\"\n    }\n  ],\n  \"sectionsEn\": [\n    {\n      \"heading\": \"1. Sinoatrial Node (Nodus sinuatrialis)\",\n      \"body\": \"Located in the superior wall of the right atrium near the superior vena cava opening, acting as the primary physiological pacemaker through spontaneous depolarization.\"\n    },\n    {\n      \"heading\": \"2. Atrioventricular Node & His-Purkinje Network\",\n      \"body\": \"Introduces a brief physiological delay (~0.09s) ensuring complete atrial contraction and ventricular filling prior to ventricular systole.\"\n    },\n    {\n      \"heading\": \"3. Educational Pharmacological Correlation (Non-Clinical)\",\n      \"body\": \"Understanding ion channels and Beta-1 adrenergic receptors in nodal tissue illustrates theoretical chronotropic and dromotropic modulation for academic study.\"\n    }\n  ],\n  \"sourceIds\": [\"src-ta2-fipat\", \"src-ncbi-bookshelf-statpearls\"]\n}\n";

