export const RESPIRATORY_PACK_LESSON_RAW = "{\n  \"canonicalId\": \"lesson-respiratory-gas-exchange-v1\",\n  \"packId\": \"respiratory-diseases-ar-v1\",\n  \"organId\": \"organ-lungs\",\n  \"systemId\": \"sys-respiratory\",\n  \"revision\": 1,\n  \"titleAr\": \"حزمة الفيزيولوجيا المرضية لأمراض الجهاز التنفسي وتبادل الغازات السنخي\",\n  \"titleEn\": \"Respiratory Diseases Pathophysiology & Alveolar Gas Exchange Pack\",\n  \"reviewStatus\": \"verified\",\n  \"importedAt\": \"2026-10-22T12:00:00Z\",\n  \"humanReviewedAt\": \"2026-10-22T14:00:00Z\",\n  \"license\": \"CC-BY-4.0 (Dawa & Hayah Educational Pack)\",\n  \"attribution\": \"دواء وحياة — الدكتور الصيدلاني معتز العلقمي — 2026 م.\",\n  \"sectionsAr\": [\n    {\n      \"heading\": \"1. الغشاء السنخي الشعري وقانون فيك للانتشار (Alveolar-Capillary Membrane)\",\n      \"body\": \"يتكون الحاجز الدموي الهوائي في الأسناخ الرئوية (Alveoli pulmonis) من الخلايا الظهارية السنخية من النمط الأول (Type I Pneumocytes) والغشاء القاعدي المشترك والخلايا البطانية للشعيرات الرئوية، بسمك لا يتجاوز 0.2 إلى 0.5 ميكرومتر. تفرز الخلايا السنخية من النمط الثاني (Type II Pneumocytes) مادة السورفاكتانت (Pulmonary Surfactant) لخفض التوتر السطحي ومنع انخماص الأسناخ أثناء الزفير.\"\n    },\n    {\n      \"heading\": \"2. الآلية المرضية لفرط الاستجابة القصبية في الربو مقابل الداء الرئوي الانسدادي المزمن\",\n      \"body\": \"في الربو القصبي (Bronchial Asthma) يقود الالتهاب اليوزيني بوساطة الخلايا التائية المساعدة (Th2) والإنترلوكينات (IL-4, IL-5, IL-13) إلى تشنج العضلات الملساء القصبية القابل للعكس. أما في الداء الرئوي الانسدادي المزمن (COPD) فيؤدي الإجهاد التأكسدي المزمن ونشاط العدلات والبلعميات إلى تحطيم الجدران السنخية (Emphysema) وتليف القصيبات الصغيرة.\"\n    }\n  ],\n  \"sectionsEn\": [\n    {\n      \"heading\": \"1. Alveolar-Capillary Membrane & Fick Diffusion Law\",\n      \"body\": \"The blood-air barrier across pulmonary alveoli (Alveoli pulmonis) comprises Type I pneumocytes, fused basement membrane, and capillary endothelium (~0.2-0.5 micrometers thick). Type II pneumocytes secrete pulmonary surfactant to reduce surface tension and prevent alveolar collapse.\"\n    },\n    {\n      \"heading\": \"2. Pathophysiology of Asthma vs. COPD Airway Remodeling\",\n      \"body\": \"In bronchial asthma, Th2-mediated eosinophilic inflammation drives reversible bronchospasm and mucus hypersecretion. In COPD, neutrophilic/macrophage protease imbalance destroys alveolar septa (emphysema) and narrows small airways.\"\n    }\n  ],\n  \"sourceIds\": [\n    \"src-who-icd11\",\n    \"src-ncbi-bookshelf-statpearls\",\n    \"src-nice-guidelines\"\n  ]\n}";

